import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Concatenates the migrations, in order, into supabase/_combined.sql so the
 * whole schema can be pasted into the Supabase SQL Editor in one go.
 *
 * The output is generated and git-ignored; the migrations themselves stay the
 * source of truth.
 */
const DIR = 'supabase/migrations';
const OUT = 'supabase/_combined.sql';

const files = readdirSync(DIR).filter((name) => name.endsWith('.sql')).sort();

const header = [
  '-- Generated by `npm run db:bundle` — do not edit.',
  '-- Every migration, in order. Paste into the Supabase SQL Editor and run.',
  '',
];

const body = files.flatMap((name) => [
  '-- ===================================================================',
  `-- ${name}`,
  '-- ===================================================================',
  readFileSync(join(DIR, name), 'utf8'),
  '',
]);

const verification = [
  '-- Verification: the tables that should now exist, and their policies.',
  "select tablename,",
  '       rowsecurity as rls_enabled,',
  '       (select count(*) from pg_policies p where p.tablename = t.tablename) as policies',
  'from pg_tables t',
  "where schemaname = 'public'",
  'order by tablename;',
];

writeFileSync(OUT, [...header, ...body, ...verification].join('\n'), 'utf8');
console.log(`Wrote ${OUT} from ${files.length} migrations.`);
